// HasWorkBlocker applies the HasEdge predicate on the "work_blocker" edge.
func HasWorkBlocker() predicate.WorkBlockerImpact {
	return predicate.WorkBlockerImpact(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, WorkBlockerTable, WorkBlockerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkBlockerWith applies the HasEdge predicate on the "work_blocker" edge with a given conditions (other predicates).
func HasWorkBlockerWith(preds ...predicate.WorkBlocker) predicate.WorkBlockerImpact {
	return predicate.WorkBlockerImpact(func(s *sql.Selector) {
		step := newWorkBlockerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

