// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkBlockerImpact) predicate.WorkBlockerImpact {
	return predicate.WorkBlockerImpact(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkBlockerImpact) predicate.WorkBlockerImpact {
	return predicate.WorkBlockerImpact(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkBlockerImpact) predicate.WorkBlockerImpact {
	return predicate.WorkBlockerImpact(sql.NotPredicates(p))
}
